  "types": "dist/index.d.ts",
  "bin": {
    "ssg": "dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "jest",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "gray-matter": "^4.0.3",
    "marked": "^12.0.0"
  },
  "devDependencies": {
    "@types/gray-matter": "^4.2.1",
    "@types/jest": "^29.5.12",
    "@types/node": "^20.11.0",
    "jest": "^29.7.0",
    "ts-jest": "^29.1.2",
    "typescript": "^5.4.0"
  }
}

export interface Frontmatter {
  title?: string;
  date?: string;
  tags: string[];
}

export interface Page {
  slug: string;
  source: string;
  title: string;
  date?: string;
  tags: string[];
  body: string;
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import matter from 'gray-matter';
import { marked } from 'marked';
import { Frontmatter } from './types';

export function parseFrontmatter(source: string): Frontmatter & { body: string } {
  const parsed = matter(source);
  const data = (parsed.data ?? {}) as Record<string, unknown>;

  const title = typeof data.title === 'string' ? data.title.trim() : undefined;
  const date =
    typeof data.date === 'string' || typeof data.date === 'number' || data.date instanceof Date
      ? new Date(data.date as string | number | Date).toISOString()
      : undefined;

  let tags: string[] = [];
  if (Array.isArray(data.tags)) {
    tags = data.tags
      .filter((t): t is string => typeof t === 'string')
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
  } else if (typeof data.tags === 'string') {
    tags = data.tags
      .split(',')
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
  }

  return { title, date, tags, body: parsed.content };
}

export async function renderMarkdown(markdown: string): Promise<string> {
  const html = await marked.parse(markdown);
  return html;
}

import fs from 'fs/promises';
import path from 'path';
import { parseFrontmatter, renderMarkdown } from './markdown';
import { BuildOptions, Page } from './types';

const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);

export function isMarkdownFile(fileName: string): boolean {
  return MARKDOWN_EXTENSIONS.has(path.extname(fileName).toLowerCase());
}

export function slugFromSource(source: string): string {
  const withoutExt = source.replace(/\.md$/i, '').replace(/\.markdown$/i, '');
  const slug = withoutExt
    .split(/[\\/]+/)
    .map((segment) =>
      segment.replace(/[\s_]+/g, '-').replace(/[^a-zA-Z0-9-]/g, '')
    )
    .join('/');
  return slug.replace(/^-+|-+$/g, '').replace(/\/+/g, '/');
}

export function titleFromSource(source: string): string {
  const slug = slugFromSource(source);
  const name = slug.split('/').pop() ?? slug;
  return name
    .split('-')
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export async function collectMarkdownFiles(contentDir: string): Promise<string[]> {
  const files: string[] = [];

  async function walk(dir: string, relative: string): Promise<void> {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const entry of entries) {
      const relPath = path.join(relative, entry.name);
      const absPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(absPath, relPath);
      } else if (entry.isFile() && isMarkdownFile(entry.name)) {
        files.push(relPath);
      }
    }
  }

  await walk(contentDir, '');
  return files;
}

export async function buildPage(contentDir: string, source: string): Promise<Page> {
  const absPath = path.join(contentDir, source);
  const raw = await fs.readFile(absPath, 'utf-8');
  const { title, date, tags, body } = parseFrontmatter(raw);
  const html = await renderMarkdown(body);

  return {
    slug: slugFromSource(source),
    source,
    title: title ?? titleFromSource(source),
    date,
    tags,
    body,
    html,
  };
}

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPageHtml(page: Page): string {
  const title = escapeHtml(page.title);
  const date = page.date
    ? `<p class="page-date">${escapeHtml(page.date)}</p>`
    : '';
  const tags = page.tags.length
    ? `<ul class="page-tags">${page.tags
        .map((tag) => `<li class="tag">${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  <article>
    <h1>${title}</h1>
    ${date}
    ${tags}
    <div class="content">
${page.html}
    </div>
  </article>
</body>
</html>
`;
}

function comparePages(a: Page, b: Page): number {
  if (a.date && b.date) {
    const cmp = new Date(b.date).getTime() - new Date(a.date).getTime();
    if (cmp !== 0) return cmp;
  }
  if (a.date && !b.date) return -1;
  if (!a.date && b.date) return 1;
  return a.title.localeCompare(b.title);
}

export function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .slice()
    .sort(comparePages)
    .map((page) => {
      const href = `${page.slug}.html`;
      const date = page.date
        ? `<span class="index-date">${escapeHtml(page.date)}</span>`
        : '';
      const tags = page.tags.length
        ? ` <span class="index-tags">[${page.tags
            .map((tag) => escapeHtml(tag))
            .join(', ')}]</span>`
        : '';
      return `    <li><a href="${escapeHtml(href)}">${escapeHtml(page.title)}</a>${date}${tags}</li>`;
    })
    .join('\n');

  const total = pages.length;
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <h1>Pages</h1>
  ${items.length ? `<ul>\n${items}\n</ul>` : '<p>No pages yet.</p>'}
  <p class="footer">${total} page${total === 1 ? '' : 's'}</p>
</body>
</html>
`;
}

export async function buildSite(options: BuildOptions): Promise<Page[]> {
  const { contentDir, outputDir } = options;

  const sources = await collectMarkdownFiles(contentDir);
  const pages: Page[] = [];
  for (const source of sources) {
    pages.push(await buildPage(contentDir, source));
  }

  await fs.rm(outputDir, { recursive: true, force: true });
  await fs.mkdir(outputDir, { recursive: true });

  for (const page of pages) {
    const relHtml = `${page.slug}.html`;
    const dest = path.join(outputDir, relHtml);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.writeFile(dest, renderPageHtml(page), 'utf-8');
  }

  await fs.writeFile(
    path.join(outputDir, 'index.html'),
    renderIndexHtml(pages),
    'utf-8'
  );

  return pages;
}

import path from 'path';
import { buildSite } from './build';
import { BuildOptions } from './types';

const DEFAULT_CONTENT_DIR = './content';
const DEFAULT_OUTPUT_DIR = './dist';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
}

export function printHelp(): void {
  console.log(`Usage: ssg build [options]

A static site generator that converts Markdown into HTML.

Commands:
  build    Generate the site from the content directory

Options:
  -c, --content <dir>   Content directory containing Markdown files (default: ${DEFAULT_CONTENT_DIR})
  -o, --output <dir>    Output directory for generated HTML (default: ${DEFAULT_OUTPUT_DIR})
  -h, --help            Show this help message
`);
}

export function parseArgs(argv: string[]): {
  command?: string;
  options: CliOptions;
  help: boolean;
} {
  const args = argv.slice(2);
  let command: string | undefined;
  const options: CliOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
  };
  let help = false;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    switch (arg) {
      case 'build':
        command = 'build';
        break;
      case '-h':
      case '--help':
        help = true;
        break;
      case '-c':
      case '--content': {
        const value = args[++i];
        if (!value || value.startsWith('-')) {
          throw new Error(`Missing value for option ${arg}`);
        }
        options.contentDir = value;
        break;
      }
      case '-o':
      case '--output': {
        const value = args[++i];
        if (!value || value.startsWith('-')) {
          throw new Error(`Missing value for option ${arg}`);
        }
        options.outputDir = value;
        break;
      }
      default:
        throw new Error(`Unknown option or command: ${arg}`);
    }
  }

  return { command, options, help };
}

export async function run(argv: string[]): Promise<void> {
  const parsed = parseArgs(argv);

  if (parsed.help || parsed.command !== 'build') {
    printHelp();
    return;
  }

  const options: BuildOptions = {
    contentDir: path.resolve(parsed.options.contentDir),
    outputDir: path.resolve(parsed.options.outputDir),
  };

  const pages = await buildSite(options);
  console.log(
    `Generated ${pages.length} page${pages.length === 1 ? '' : 's'} in ${options.outputDir}`
  );
}

if (require.main === module) {
  run(process.argv).catch((err: unknown) => {
    const message = err instanceof Error ? err.message : String(err);
    console.error(`ssg: ${message}`);
    process.exit(1);
  });
}

export { buildSite, renderPageHtml, renderIndexHtml, collectMarkdownFiles } from './build';
export { parseFrontmatter, renderMarkdown } from './markdown';
export { parseArgs, run, printHelp } from './cli';
export type { Page, Frontmatter, BuildOptions } from './types';

import { parseFrontmatter, renderMarkdown } from '../markdown';

describe('parseFrontmatter', () => {
  it('parses title, date, and tags from frontmatter', () => {
    const source = `---
title: Hello World
date: 2024-01-15
tags: [typescript, web]
---
# Heading
Some **bold** text.
`;

    const result = parseFrontmatter(source);
    expect(result.title).toBe('Hello World');
    expect(result.date).toBe('2024-01-15T00:00:00.000Z');
    expect(result.tags).toEqual(['typescript', 'web']);
    expect(result.body).toContain('# Heading');
  });

  it('parses tags given as a comma-separated string', () => {
    const source = `---
title: Comma Tags
tags: one, two, three
---
Body
`;
    const result = parseFrontmatter(source);
    expect(result.tags).toEqual(['one', 'two', 'three']);
  });

  it('handles missing frontmatter gracefully', () => {
    const result = parseFrontmatter('Just a plain markdown body.');
    expect(result.title).toBeUndefined();
    expect(result.date).toBeUndefined();
    expect(result.tags).toEqual([]);
    expect(result.body).toBe('Just a plain markdown body.');
  });
});

describe('renderMarkdown', () => {
  it('is asynchronous and returns HTML', async () => {
    const html = await renderMarkdown('# Title\n\nHello **world**');
    expect(html).toContain('<h1>Title</h1>');
    expect(html).toContain('<strong>world</strong>');
  });

  it('awaits the async parse() promise (marked v12+)', async () => {
    const promise = renderMarkdown('## Async parse');
    expect(promise).toBeInstanceOf(Promise);
    const html = await promise;
    expect(html).toContain('<h2>Async parse</h2>');
  });
});

import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import {
  buildSite,
  slugFromSource,
  titleFromSource,
  collectMarkdownFiles,
} from '../build';

async function makeTempDir(): Promise<string> {
  return fs.mkdtemp(path.join(os.tmpdir(), 'ssg-test-'));
}

async function write(filePath: string, content: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, content, 'utf-8');
}

describe('slugFromSource', () => {
  it('maps a relative path to a html slug', () => {
    expect(slugFromSource('hello-world.md')).toBe('hello-world');
    expect(slugFromSource('posts/my first post.markdown')).toBe('posts/my-first-post');
    expect(slugFromSource('a/b/c.md')).toBe('a/b/c');
  });
});

describe('titleFromSource', () => {
  it('derives a readable title from a filename', () => {
    expect(titleFromSource('hello-world.md')).toBe('Hello World');
  });
});

describe('collectMarkdownFiles', () => {
  it('finds markdown files recursively and ignores non-markdown', async () => {
    const dir = await makeTempDir();
    await write(path.join(dir, 'a.md'), '# A');
    await write(path.join(dir, 'sub', 'b.markdown'), '# B');
    await write(path.join(dir, 'c.txt'), 'not markdown');
    await write(path.join(dir, 'notes.md~'), 'backup');

    const files = await collectMarkdownFiles(dir);
    expect(files.sort()).toEqual(['a.md', 'sub/b.markdown']);
  });
});

describe('buildSite', () => {
  it('generates index.html and a page per markdown file', async () => {
    const root = await makeTempDir();
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'dist');

    await write(
      path.join(contentDir, 'hello.md'),
      `---
title: Hello World
date: 2024-03-01
tags: [intro, demo]
---
# Hello
Welcome to **the site**.
`
    );
    await write(
      path.join(contentDir, 'posts', 'second.md'),
      `---
title: Second Post
date: 2024-01-01
tags: [blog]
---
Some *second* content.
`
    );

    const pages = await buildSite({ contentDir, outputDir });

    expect(pages).toHaveLength(2);

    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('<h1>Pages</h1>');
    expect(index).toContain('href="hello.html"');
    expect(index).toContain('Hello World');
    expect(index).toContain('href="posts/second.html"');
    expect(index).toContain('Second Post');

    const hello = await fs.readFile(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(hello).toContain('<title>Hello World</title>');
    expect(hello).toContain('<h1>Hello World</h1>');
    expect(hello).toContain('<strong>the site</strong>');
    expect(hello).toContain('class="tag">intro');
    expect(hello).toContain('href="index.html"');

    const second = await fs.readFile(
      path.join(outputDir, 'posts', 'second.html'),
      'utf-8'
    );
    expect(second).toContain('Second Post');
  });

  it('sorts the index by date (newest first) and falls back to title', async () => {
    const root = await makeTempDir();
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'dist');

    await write(path.join(contentDir, 'older.md'), '---\ndate: 2020-01-01\n---\nOld');
    await write(path.join(contentDir, 'newer.md'), '---\ndate: 2025-01-01\n---\nNew');

    await buildSite({ contentDir, outputDir });
    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
    const newerPos = index.indexOf('Older');
    const olderPos = index.indexOf('Newer');
    expect(newerPos).toBeLessThan(olderPos);
  });

  it('falls back to a filename-derived title when title is missing', async () => {
    const root = await makeTempDir();
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'dist');

    await write(path.join(contentDir, 'no-title.md'), 'Just content.');

    await buildSite({ contentDir, outputDir });
    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('No Title');
  });

  it('writes an empty index when there is no markdown content', async () => {
    const root = await makeTempDir();
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'dist');
    await fs.mkdir(contentDir, { recursive: true });

    const pages = await buildSite({ contentDir, outputDir });
    expect(pages).toEqual([]);

    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('No pages yet.');
  });

